1	//! Shared types and helpers for compliance export formats.
2	//!
3	//! Provides `AuditRequest`, `AuditFormat`, `AuditStats`, and helper
4	//! functions that query provenance.db and cost.db for a given date range.
5	
6	use anyhow::{Context, Result};
7	use std::path::PathBuf;
8	
9	use crate::core::cost_store::CostStore;
10	use crate::core::provenance::{ProvenanceRecord, ProvenanceStore};
11	
12	// ── Public types ──────────────────────────────────────────────────────────────
13	
14	/// Specifies which compliance export format to produce.
15	#[derive(Debug, Clone, PartialEq)]
16	pub enum AuditFormat {
17	    Slsa,
18	    CycloneDx,
19	    Soc2,
20	    EuAiAct,
21	    All,
22	}
23	
24	impl AuditFormat {
25	    /// Parse from a CLI string value (case-insensitive).
26	    pub fn from_str(s: &str) -> Option<Self> {
27	        match s.to_lowercase().as_str() {
28	            "slsa" => Some(Self::Slsa),
29	            "cyclonedx" => Some(Self::CycloneDx),
30	            "soc2" => Some(Self::Soc2),
31	            "eu-ai-act" | "euaiact" => Some(Self::EuAiAct),
32	            "all" => Some(Self::All),
33	            _ => None,
34	        }
35	    }
36	
37	    /// Human-readable label for display.
38	    pub fn label(&self) -> &'static str {
39	        match self {
40	            Self::Slsa => "SLSA Provenance v1.0",
41	            Self::CycloneDx => "CycloneDX SBOM",
42	            Self::Soc2 => "SOC 2 Type II",
43	            Self::EuAiAct => "EU AI Act Annex IV",
44	            Self::All => "All Formats",
45	        }
46	    }
47	}
48	
49	/// Parameters for an audit export run.
50	#[allow(dead_code)]
51	pub struct AuditRequest {
52	    pub format: AuditFormat,
53	    pub range_days: u32,
54	    pub project_filter: Option<String>,
55	    pub dev_filter: Option<String>,
56	    pub output_dir: Option<PathBuf>,
57	}
58	
59	impl Default for AuditRequest {
60	    fn default() -> Self {
61	        Self {
62	            format: AuditFormat::Slsa,
63	            range_days: 90,
64	            project_filter: None,
65	            dev_filter: None,
66	            output_dir: None,
67	        }
68	    }
69	}
70	
71	/// Aggregated statistics gathered from the local databases.
72	#[allow(dead_code)]
73	#[derive(Debug, Clone)]
74	pub struct AuditStats {
75	    pub total_provenance: u64,
76	    pub total_cost_usd: f64,
77	    pub quality_findings: u64,
78	    /// (from_rfc3339, to_rfc3339)
79	    pub date_range: (String, String),
80	}
81	
82	// ── Date range helpers ────────────────────────────────────────────────────────
83	
84	/// Convert a range specifier string to a start ISO-8601 timestamp (UTC).
85	///
86	/// Supported values: "30d", "90d", "1y", "all"
87	/// Returns `None` for "all" (no lower bound).
88	pub fn range_to_since(range: &str) -> Option<String> {
89	    let days: i64 = match range.to_lowercase().as_str() {
90	        "all" => return None,
91	        "30d" => 30,
92	        "90d" => 90,
93	        "1y" => 365,
94	        other => {
95	            // Try bare integer "NNd"
96	            if let Some(stripped) = other.strip_suffix('d') {
97	                stripped.parse::<i64>().ok()?
98	            } else {
99	                other.parse::<i64>().ok()?
100	            }
101	        }
102	    };
103	    let since = chrono::Utc::now() - chrono::Duration::days(days);
104	    Some(since.to_rfc3339())
105	}
106	
107	/// Convert a `range_days` integer to an RFC3339 start timestamp.
108	pub fn days_to_since(days: u32) -> String {
109	    let since = chrono::Utc::now() - chrono::Duration::days(days as i64);
110	    since.to_rfc3339()
111	}
112	
113	// ── Database query helpers ────────────────────────────────────────────────────
114	
115	/// Query all provenance records within a date range.
116	///
117	/// `since_rfc3339` is an inclusive lower bound; `None` returns all records.
118	pub fn query_provenance_records(
119	    since_rfc3339: Option<&str>,
120	    project_filter: Option<&str>,
121	    dev_filter: Option<&str>,
122	) -> Result<Vec<ProvenanceRecord>> {
123	    let store = match ProvenanceStore::new() {
124	        Ok(s) => s,
125	        Err(_) => return Ok(Vec::new()), // DB does not exist yet — empty export
126	    };
127	
128	    store
129	        .query_range(since_rfc3339, project_filter, dev_filter)
130	        .context("failed to query provenance records")
131	}
132	
133	/// Gather aggregate statistics from both databases for the given range.
134	pub fn gather_stats(
135	    since_rfc3339: Option<&str>,
136	    project_filter: Option<&str>,
137	    dev_filter: Option<&str>,
138	) -> Result<AuditStats> {
139	    let records = query_provenance_records(since_rfc3339, project_filter, dev_filter)?;
140	    let total_provenance = records.len() as u64;
141	
142	    let total_cost_usd = match CostStore::new() {
143	        Ok(store) => {
144	            if let Some(since) = since_rfc3339 {
145	                store.total_cost_since(since).unwrap_or(0.0)
146	            } else {
147	                store.total_cost(None).unwrap_or(0.0)
148	            }
149	        }
150	        Err(_) => 0.0,
151	    };
152	
153	    let now = chrono::Utc::now().to_rfc3339();
154	    let from = since_rfc3339.unwrap_or("epoch").to_string();
155	
156	    Ok(AuditStats {
157	        total_provenance,
158	        total_cost_usd,
159	        quality_findings: 0, // Phase 5 stub — quality gate integration is post-MVP
160	        date_range: (from, now),
161	    })
162	}
163	
164	// ── Tests ─────────────────────────────────────────────────────────────────────
165	
166	#[cfg(test)]
167	mod tests {
168	    use super::*;
169	
170	    #[test]
171	    fn audit_format_from_str_roundtrip() {
172	        assert_eq!(AuditFormat::from_str("slsa"), Some(AuditFormat::Slsa));
173	        assert_eq!(AuditFormat::from_str("SLSA"), Some(AuditFormat::Slsa));
174	        assert_eq!(
175	            AuditFormat::from_str("cyclonedx"),
176	            Some(AuditFormat::CycloneDx)
177	        );
178	        assert_eq!(AuditFormat::from_str("soc2"), Some(AuditFormat::Soc2));
179	        assert_eq!(
180	            AuditFormat::from_str("eu-ai-act"),
181	            Some(AuditFormat::EuAiAct)
182	        );
183	        assert_eq!(AuditFormat::from_str("all"), Some(AuditFormat::All));
184	        assert_eq!(AuditFormat::from_str("unknown"), None);
185	    }
186	
187	    #[test]
188	    fn range_to_since_all_returns_none() {
189	        assert_eq!(range_to_since("all"), None);
190	    }
191	
192	    #[test]
193	    fn range_to_since_30d_returns_some() {
194	        let result = range_to_since("30d");
195	        assert!(result.is_some());
196	        let ts = result.unwrap();
197	        // Should be a valid RFC3339 timestamp
198	        assert!(ts.contains('T'));
199	    }
200	
201	    #[test]
202	    fn range_to_since_90d_is_before_30d() {
203	        let since_90 = range_to_since("90d").unwrap();
204	        let since_30 = range_to_since("30d").unwrap();
205	        // 90d ago is earlier (lexicographically smaller ISO timestamp)
206	        assert!(since_90 < since_30);
207	    }
208	
209	    #[test]
210	    fn range_to_since_1y_returns_some() {
211	        let result = range_to_since("1y");
212	        assert!(result.is_some());
213	    }
214	
215	    #[test]
216	    fn days_to_since_produces_valid_timestamp() {
217	        let ts = days_to_since(90);
218	        assert!(ts.contains('T'));
219	        assert!(ts.contains('+') || ts.ends_with('Z'));
220	    }
221	
222	    #[test]
223	    fn gather_stats_empty_db_succeeds() {
224	        let dir = tempfile::tempdir().unwrap();
225	        let prov_db = dir.path().join("provenance.db");
226	        let cost_db = dir.path().join("cost.db");
227	        std::env::set_var("RTK_PROVENANCE_DB", prov_db.to_str().unwrap());
228	        std::env::set_var("RTK_COST_DB", cost_db.to_str().unwrap());
229	
230	        let stats = gather_stats(None, None, None);
231	
232	        std::env::remove_var("RTK_PROVENANCE_DB");
233	        std::env::remove_var("RTK_COST_DB");
234	
235	        let stats = stats.unwrap();
236	        assert_eq!(stats.total_provenance, 0);
237	        assert_eq!(stats.total_cost_usd, 0.0);
238	    }
239	
240	    #[test]
241	    fn audit_request_default_values() {
242	        let req = AuditRequest::default();
243	        assert_eq!(req.format, AuditFormat::Slsa);
244	        assert_eq!(req.range_days, 90);
245	        assert!(req.project_filter.is_none());
246	        assert!(req.dev_filter.is_none());
247	        assert!(req.output_dir.is_none());
248	    }
249	}
