1	//! SLSA Provenance v1.0 attestation export in in-toto envelope format.
2	//!
3	//! Spec: https://slsa.dev/spec/v1.0/provenance
4	//! Envelope: https://github.com/in-toto/attestation/blob/main/spec/README.md
5	//!
6	//! The payload is a base64-encoded JSON ProvenanceStatement. The envelope
7	//! contains one Ed25519 signature produced by the RTK attestation key
8	//! (see `core::attestation`).
9	
10	use anyhow::{Context, Result};
11	use serde::{Deserialize, Serialize};
12	
13	use crate::core::attestation;
14	use crate::core::provenance::ProvenanceRecord;
15	use crate::compliance::report_common::AuditStats;
16	
17	// ── in-toto envelope ──────────────────────────────────────────────────────────
18	
19	const PAYLOAD_TYPE: &str = "application/vnd.in-toto+json";
20	
21	/// One Ed25519 signature in the in-toto envelope.
22	#[derive(Debug, Clone, Serialize, Deserialize)]
23	pub struct Signature {
24	    /// Hex-encoded Ed25519 public key (keyid).
25	    pub keyid: String,
26	    /// Hex-encoded Ed25519 signature over the payload bytes.
27	    pub sig: String,
28	}
29	
30	/// in-toto Envelope wrapping a SLSA ProvenanceStatement payload.
31	///
32	/// Payload is base64url-encoded UTF-8 JSON (standard base64 with padding).
33	#[derive(Debug, Clone, Serialize, Deserialize)]
34	pub struct InTotoEnvelope {
35	    #[serde(rename = "payloadType")]
36	    pub payload_type: String,
37	    /// Base64-encoded JSON ProvenanceStatement.
38	    pub payload: String,
39	    pub signatures: Vec<Signature>,
40	}
41	
42	// ── SLSA Provenance v1.0 types ────────────────────────────────────────────────
43	
44	/// Top-level SLSA ProvenanceStatement (the decoded payload inside the envelope).
45	#[derive(Debug, Clone, Serialize, Deserialize)]
46	pub struct SlsaAttestation {
47	    /// Fixed: "https://in-toto.io/Statement/v1"
48	    #[serde(rename = "_type")]
49	    pub statement_type: String,
50	    /// Array of subject artifacts this provenance describes.
51	    pub subject: Vec<SlsaSubject>,
52	    /// Fixed: "https://slsa.dev/provenance/v1"
53	    #[serde(rename = "predicateType")]
54	    pub predicate_type: String,
55	    pub predicate: SlsaPredicate,
56	}
57	
58	/// A subject artifact (AI-generated file + its SHA-256 hash).
59	#[derive(Debug, Clone, Serialize, Deserialize)]
60	pub struct SlsaSubject {
61	    pub name: String,
62	    pub digest: SlsaDigest,
63	}
64	
65	/// Digest map — at minimum `sha256`.
66	#[derive(Debug, Clone, Serialize, Deserialize)]
67	pub struct SlsaDigest {
68	    pub sha256: String,
69	}
70	
71	/// SLSA v1 predicate.
72	#[derive(Debug, Clone, Serialize, Deserialize)]
73	pub struct SlsaPredicate {
74	    #[serde(rename = "buildDefinition")]
75	    pub build_definition: BuildDefinition,
76	    #[serde(rename = "runDetails")]
77	    pub run_details: RunDetails,
78	}
79	
80	/// Build definition — external parameters + resolved dependencies.
81	#[derive(Debug, Clone, Serialize, Deserialize)]
82	pub struct BuildDefinition {
83	    /// Fixed build type URI identifying this is an AI provenance attestation.
84	    #[serde(rename = "buildType")]
85	    pub build_type: String,
86	    #[serde(rename = "externalParameters")]
87	    pub external_parameters: ExternalParameters,
88	    #[serde(rename = "resolvedDependencies")]
89	    pub resolved_dependencies: Vec<ResolvedDependency>,
90	}
91	
92	/// User-supplied parameters that drove the build.
93	#[derive(Debug, Clone, Serialize, Deserialize)]
94	pub struct ExternalParameters {
95	    pub project: String,
96	    #[serde(rename = "dateFrom")]
97	    pub date_from: String,
98	    #[serde(rename = "dateTo")]
99	    pub date_to: String,
100	}
101	
102	/// One AI-generated file dependency entry.
103	#[derive(Debug, Clone, Serialize, Deserialize)]
104	pub struct ResolvedDependency {
105	    pub uri: String,
106	    pub digest: SlsaDigest,
107	    /// Session ID that produced this file.
108	    #[serde(rename = "sessionId")]
109	    pub session_id: String,
110	    /// Model that generated the file.
111	    #[serde(rename = "modelId")]
112	    pub model_id: String,
113	    pub contributor: String,
114	    pub timestamp: String,
115	}
116	
117	/// Run details — builder + metadata.
118	#[derive(Debug, Clone, Serialize, Deserialize)]
119	pub struct RunDetails {
120	    pub builder: Builder,
121	    pub metadata: RunMetadata,
122	}
123	
124	/// Builder identity.
125	#[derive(Debug, Clone, Serialize, Deserialize)]
126	pub struct Builder {
127	    pub id: String,
128	    pub version: String,
129	}
130	
131	/// Run-level metadata.
132	#[derive(Debug, Clone, Serialize, Deserialize)]
133	pub struct RunMetadata {
134	    #[serde(rename = "invocationId")]
135	    pub invocation_id: String,
136	    #[serde(rename = "startedOn")]
137	    pub started_on: String,
138	    #[serde(rename = "finishedOn")]
139	    pub finished_on: String,
140	    #[serde(rename = "totalProvenance")]
141	    pub total_provenance: u64,
142	    #[serde(rename = "totalCostUsd")]
143	    pub total_cost_usd: f64,
144	}
145	
146	// ── Builder constant ──────────────────────────────────────────────────────────
147	
148	const BUILD_TYPE: &str = "https://codeflow.dev/ai-provenance/v1";
149	const BUILDER_ID: &str = "https://codeflow.dev/rtk";
150	
151	// ── Main generation function ──────────────────────────────────────────────────
152	
153	/// Generate a signed in-toto envelope containing a SLSA v1 provenance statement.
154	///
155	/// Returns an `InTotoEnvelope` with the payload base64-encoded and one
156	/// Ed25519 signature from the RTK attestation key.
157	pub fn generate_slsa(
158	    records: &[ProvenanceRecord],
159	    stats: &AuditStats,
160	) -> Result<InTotoEnvelope> {
161	    let attestation = build_attestation(records, stats);
162	    let payload_json =
163	        serde_json::to_string(&attestation).context("failed to serialize SLSA attestation")?;
164	
165	    // Sign the raw payload bytes (not base64 — sign-what-you-serialize).
166	    let keypair = attestation::load_or_generate()
167	        .context("failed to load/generate attestation key")?;
168	
169	    let sig_hex = keypair.sign(payload_json.as_bytes());
170	    let keyid = keypair.public_key_hex();
171	
172	    // Encode payload as standard base64 (RFC 4648 with padding).
173	    use base64::{Engine as _, engine::general_purpose::STANDARD};
174	    let payload_b64 = STANDARD.encode(payload_json.as_bytes());
175	
176	    Ok(InTotoEnvelope {
177	        payload_type: PAYLOAD_TYPE.to_string(),
178	        payload: payload_b64,
179	        signatures: vec![Signature {
180	            keyid,
181	            sig: sig_hex,
182	        }],
183	    })
184	}
185	
186	fn build_attestation(records: &[ProvenanceRecord], stats: &AuditStats) -> SlsaAttestation {
187	    let (date_from, date_to) = &stats.date_range;
188	
189	    // Subjects: one entry per unique (file_path, code_hash) pair.
190	    let mut seen_subjects: std::collections::HashSet<String> = std::collections::HashSet::new();
191	    let mut subjects: Vec<SlsaSubject> = Vec::new();
192	    for r in records {
193	        let key = format!("{}:{}", r.file_path, r.code_hash);
194	        if seen_subjects.insert(key) {
195	            subjects.push(SlsaSubject {
196	                name: r.file_path.clone(),
197	                digest: SlsaDigest {
198	                    sha256: r.code_hash.clone(),
199	                },
200	            });
201	        }
202	    }
203	
204	    // Resolved dependencies: one entry per provenance record.
205	    let resolved_dependencies: Vec<ResolvedDependency> = records
206	        .iter()
207	        .map(|r| ResolvedDependency {
208	            uri: format!("file://{}", r.file_path),
209	            digest: SlsaDigest {
210	                sha256: r.code_hash.clone(),
211	            },
212	            session_id: r.session_id.clone(),
213	            model_id: r.model_id.clone(),
214	            contributor: r.contributor_type.as_str().to_string(),
215	            timestamp: r.timestamp.clone(),
216	        })
217	        .collect();
218	
219	    let project = std::env::current_dir()
220	        .ok()
221	        .and_then(|p| p.file_name().map(|n| n.to_string_lossy().into_owned()))
222	        .unwrap_or_else(|| "unknown".to_string());
223	
224	    let invocation_id = format!("rtk-audit-{}", chrono::Utc::now().timestamp());
225	    let now = chrono::Utc::now().to_rfc3339();
226	
227	    SlsaAttestation {
228	        statement_type: "https://in-toto.io/Statement/v1".to_string(),
229	        subject: subjects,
230	        predicate_type: "https://slsa.dev/provenance/v1".to_string(),
231	        predicate: SlsaPredicate {
232	            build_definition: BuildDefinition {
233	                build_type: BUILD_TYPE.to_string(),
234	                external_parameters: ExternalParameters {
235	                    project,
236	                    date_from: date_from.clone(),
237	                    date_to: date_to.clone(),
238	                },
239	                resolved_dependencies,
240	            },
241	            run_details: RunDetails {
242	                builder: Builder {
243	                    id: BUILDER_ID.to_string(),
244	                    version: env!("CARGO_PKG_VERSION").to_string(),
245	                },
246	                metadata: RunMetadata {
247	                    invocation_id,
248	                    started_on: date_from.clone(),
249	                    finished_on: now,
250	                    total_provenance: stats.total_provenance,
251	                    total_cost_usd: stats.total_cost_usd,
252	                },
253	            },
254	        },
255	    }
256	}
257	
258	/// Decode the base64 payload from an envelope and deserialize into `SlsaAttestation`.
259	pub fn decode_payload(envelope: &InTotoEnvelope) -> Result<SlsaAttestation> {
260	    use base64::{Engine as _, engine::general_purpose::STANDARD};
261	    let bytes = STANDARD
262	        .decode(&envelope.payload)
263	        .context("invalid base64 in envelope payload")?;
264	    serde_json::from_slice(&bytes).context("invalid JSON in SLSA payload")
265	}
266	
267	/// Verify the first envelope signature against the decoded payload.
268	pub fn verify_envelope_signature(envelope: &InTotoEnvelope) -> Result<bool> {
269	    use base64::{Engine as _, engine::general_purpose::STANDARD};
270	    if envelope.signatures.is_empty() {
271	        return Ok(false);
272	    }
273	    let payload_bytes = STANDARD
274	        .decode(&envelope.payload)
275	        .context("invalid base64 in envelope payload")?;
276	    let sig = &envelope.signatures[0];
277	    attestation::verify(&sig.keyid, &payload_bytes, &sig.sig)
278	}
