281	
282	#[cfg(test)]
283	mod tests {
284	    use super::*;
285	    use crate::compliance::report_common::AuditStats;
286	    use crate::core::provenance::{ContributorType, ProvenanceRecord};
287	
288	    fn make_record(file: &str, code_hash: &str, model: &str) -> ProvenanceRecord {
289	        ProvenanceRecord {
290	            id: Some(1),
291	            model_id: model.to_string(),
292	            model_version: "1.0".to_string(),
293	            prompt_hash: "abc".to_string(),
294	            code_hash: code_hash.to_string(),
295	            file_path: file.to_string(),
296	            start_line: 1,
297	            end_line: 50,
298	            contributor_type: ContributorType::Ai,
299	            attestation_sig: "deadsig".to_string(),
300	            timestamp: "2025-01-01T00:00:00+00:00".to_string(),
301	            developer_id: "dev@example.com".to_string(),
302	            session_id: "sess_001".to_string(),
303	        }
304	    }
305	
306	    fn empty_stats() -> AuditStats {
307	        AuditStats {
308	            total_provenance: 0,
309	            total_cost_usd: 0.0,
310	            quality_findings: 0,
311	            date_range: (
312	                "2025-01-01T00:00:00+00:00".to_string(),
313	                "2025-04-01T00:00:00+00:00".to_string(),
