318	    // ── 1. SLSA attestation JSON structure ───────────────────────────────────
319	
320	    #[test]
321	    fn slsa_attestation_has_correct_statement_type() {
322	        let records = vec![make_record("src/main.rs", "abc123", "claude")];
323	        let stats = AuditStats {
324	            total_provenance: 1,
325	            ..empty_stats()
326	        };
327	        let attestation = build_attestation(&records, &stats);
328	        assert_eq!(
329	            attestation.statement_type,
330	            "https://in-toto.io/Statement/v1"
331	        );
332	    }
333	
334	    #[test]
335	    fn slsa_attestation_predicate_type_is_slsa_v1() {
336	        let stats = empty_stats();
337	        let att = build_attestation(&[], &stats);
338	        assert_eq!(att.predicate_type, "https://slsa.dev/provenance/v1");
339	    }
340	
341	    #[test]
342	    fn slsa_build_type_is_codeflow() {
343	        let stats = empty_stats();
344	        let att = build_attestation(&[], &stats);
345	        assert_eq!(
346	            att.predicate.build_definition.build_type,
347	            "https://codeflow.dev/ai-provenance/v1"
348	        );
349	    }
350	
351	    // ── 2. In-toto envelope format ───────────────────────────────────────────
352	
353	    #[test]
354	    fn envelope_has_correct_payload_type() {
355	        let stats = empty_stats();
356	        let env = generate_slsa(&[], &stats).unwrap();
357	        assert_eq!(env.payload_type, "application/vnd.in-toto+json");
358	    }
