265	    /// Query records with optional lower-bound timestamp, project path, and developer filters.
266	    ///
267	    /// `since_rfc3339` — inclusive lower bound (e.g. "2025-01-01T00:00:00+00:00"); `None` = all.
268	    /// `project_filter` — substring match on `file_path`; `None` = no filter.
269	    /// `dev_filter`     — exact match on `developer_id`; `None` = no filter.
270	    pub fn query_range(
271	        &self,
272	        since_rfc3339: Option<&str>,
273	        project_filter: Option<&str>,
274	        dev_filter: Option<&str>,
275	    ) -> Result<Vec<ProvenanceRecord>> {
276	        // Build WHERE clauses dynamically to avoid parameter count mismatches.
277	        let mut clauses: Vec<String> = Vec::new();
278	        if since_rfc3339.is_some() {
279	            clauses.push("timestamp >= ?1".to_string());
280	        }
281	        if project_filter.is_some() {
282	            let idx = clauses.len() + 1;
283	            clauses.push(format!("file_path LIKE ?{}", idx));
284	        }
285	        if dev_filter.is_some() {
286	            let idx = clauses.len() + 1;
287	            clauses.push(format!("developer_id = ?{}", idx));
288	        }
289	
290	        let where_clause = if clauses.is_empty() {
291	            String::new()
292	        } else {
293	            format!("WHERE {}", clauses.join(" AND "))
294	        };
295	
296	        let sql = format!(
297	            "SELECT id, model_id, model_version, prompt_hash, code_hash, file_path,
298	                    start_line, end_line, contributor_type, attestation_sig,
299	                    timestamp, developer_id, session_id
300	             FROM provenance_records {} ORDER BY timestamp ASC",
301	            where_clause
302	        );
303	
304	        // Collect bound values in order.
305	        let mut bound_strings: Vec<String> = Vec::new();
306	        if let Some(since) = since_rfc3339 {
307	            bound_strings.push(since.to_string());
308	        }
309	        if let Some(proj) = project_filter {
310	            bound_strings.push(format!("%{}%", proj));
311	        }
312	        if let Some(dev) = dev_filter {
313	            bound_strings.push(dev.to_string());
314	        }
315	
316	        let mut stmt = self.conn.prepare(&sql)?;
317	        let records = stmt
318	            .query_map(
319	                rusqlite::params_from_iter(bound_strings.iter()),
320	                |row| {
321	                    Ok(ProvenanceRecord {
322	                        id: Some(row.get(0)?),
323	                        model_id: row.get(1)?,
324	                        model_version: row.get(2)?,
325	                        prompt_hash: row.get(3)?,
326	                        code_hash: row.get(4)?,
327	                        file_path: row.get(5)?,
328	                        start_line: row.get(6)?,
329	                        end_line: row.get(7)?,
330	                        contributor_type: ContributorType::from_str(&row.get::<_, String>(8)?),
331	                        attestation_sig: row.get(9)?,
332	                        timestamp: row.get(10)?,
333	                        developer_id: row.get(11)?,
334	                        session_id: row.get(12)?,
335	                    })
336	                },
337	            )?
338	            .collect::<std::result::Result<Vec<_>, _>>()?;
339	
340	        Ok(records)
341	    }
342	}
