64	pub fn load_or_generate() -> Result<KeyPair> {
65	    let dir = keys_dir()?;
66	    fs::create_dir_all(&dir)
67	        .with_context(|| format!("failed to create keys dir: {}", dir.display()))?;
68	
69	    let key_file = dir.join("ed25519.key");
70	
71	    match fs::read(&key_file) {
72	        Ok(bytes) => {
73	            let key_bytes: [u8; 32] = bytes
74	                .try_into()
75	                .map_err(|_| anyhow::anyhow!("key file corrupted: expected 32 bytes"))?;
76	            return Ok(KeyPair::from_bytes(&key_bytes));
77	        }
78	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
79	        Err(e) => return Err(e).context("failed to read key file"),
80	    }
81	
82	    let kp = KeyPair::generate();
83	
84	    match fs::OpenOptions::new()
85	        .write(true)
86	        .create_new(true)
87	        .open(&key_file)
88	    {
89	        Ok(mut f) => {
90	            use std::io::Write;
91	            f.write_all(&kp.to_bytes())
92	                .with_context(|| format!("failed to write key: {}", key_file.display()))?;
93	        }
94	        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
95	            return load_or_generate();
96	        }
97	        Err(e) => return Err(e).context("failed to create key file"),
98	    }
99	
100	    #[cfg(unix)]
101	    {
102	        use std::os::unix::fs::PermissionsExt;
103	        let _ = fs::set_permissions(&key_file, fs::Permissions::from_mode(0o600));
104	    }
105	
106	    Ok(kp)
107	}
